func vrfNameNeighborBasePath(nameName, name string) []any {
	return []any{"vrf", "name", nameName, "neighbor", name}
}

// Create sets up the VRFNameNeighbor on VyOS.
func (VRFNameNeighbor) Create(
	ctx context.Context,
	req infer.CreateRequest[VRFNameNeighborArgs],
) (infer.CreateResponse[VRFNameNeighborState], error) {
	if req.DryRun {
		return infer.CreateResponse[VRFNameNeighborState]{
			ID:     req.Inputs.Name,
			Output: VRFNameNeighborState{VRFNameNeighborArgs: req.Inputs},
		}, nil
	}

	ops := buildVRFNameNeighborOps(req.Inputs)
	client := getClient(ctx)
	if err := client.BatchConfigure(ctx, ops); err != nil {
		return infer.CreateResponse[VRFNameNeighborState]{},
			fmt.Errorf("configure VRFNameNeighbor %s: %w", req.Inputs.Name, err)
	}
	saveIfEnabled(ctx)

	return infer.CreateResponse[VRFNameNeighborState]{
		ID:     req.Inputs.Name,
		Output: VRFNameNeighborState{VRFNameNeighborArgs: req.Inputs},
	}, nil
}

// Read fetches the current VRFNameNeighbor config from VyOS.
func (VRFNameNeighbor) Read(
	ctx context.Context,
	req infer.ReadRequest[VRFNameNeighborArgs, VRFNameNeighborState],
) (infer.ReadResponse[VRFNameNeighborArgs, VRFNameNeighborState], error) {
	client := getClient(ctx)
	base := vrfNameNeighborBasePath(req.State.NameName, req.State.Name)

	data, err := client.ShowConfig(ctx, pathToStrings(base))
	if err != nil {
		if isEmptyConfigError(err) {
			// Tag node exists but has no child properties. Return minimal state.
			args := VRFNameNeighborArgs{NameName: req.State.NameName, Name: req.State.Name}
			state := VRFNameNeighborState{VRFNameNeighborArgs: args}
			return infer.ReadResponse[VRFNameNeighborArgs, VRFNameNeighborState]{
				ID:     req.State.Name,
				Inputs: args,
				State:  state,
			}, nil
		}
		return infer.ReadResponse[VRFNameNeighborArgs, VRFNameNeighborState]{},
			fmt.Errorf("read VRFNameNeighbor %s: %w", req.State.Name, err)
	}

	args, err := parseVRFNameNeighborConfig(req.State.NameName, req.State.Name, data)
	if err != nil {
		return infer.ReadResponse[VRFNameNeighborArgs, VRFNameNeighborState]{},
			fmt.Errorf("parse VRFNameNeighbor %s config: %w", req.State.Name, err)
	}

	state := VRFNameNeighborState{VRFNameNeighborArgs: args}
	return infer.ReadResponse[VRFNameNeighborArgs, VRFNameNeighborState]{
		ID:     req.State.Name,
		Inputs: args,
		State:  state,
	}, nil
}

// Update modifies an existing VRFNameNeighbor configuration.
func (VRFNameNeighbor) Update(
	ctx context.Context,
	req infer.UpdateRequest[VRFNameNeighborArgs, VRFNameNeighborState],
) (infer.UpdateResponse[VRFNameNeighborState], error) {
	if req.DryRun {
		return infer.UpdateResponse[VRFNameNeighborState]{
			Output: VRFNameNeighborState{VRFNameNeighborArgs: req.Inputs},
		}, nil
	}

	ops := buildVRFNameNeighborUpdateOps(req.State.VRFNameNeighborArgs, req.Inputs)
	if len(ops) > 0 {
		client := getClient(ctx)
		if err := client.BatchConfigure(ctx, ops); err != nil {
			return infer.UpdateResponse[VRFNameNeighborState]{},
				fmt.Errorf("update VRFNameNeighbor %s: %w", req.Inputs.Name, err)
		}
		saveIfEnabled(ctx)
	}

	return infer.UpdateResponse[VRFNameNeighborState]{
		Output: VRFNameNeighborState{VRFNameNeighborArgs: req.Inputs},
	}, nil
}

// Delete removes the VRFNameNeighbor configuration from VyOS.
func (VRFNameNeighbor) Delete(
	ctx context.Context,
	req infer.DeleteRequest[VRFNameNeighborState],
) (infer.DeleteResponse, error) {
	client := getClient(ctx)
	base := vrfNameNeighborBasePath(req.State.NameName, req.State.Name)
	if err := client.Delete(ctx, pathToStrings(base)); err != nil {
		return infer.DeleteResponse{}, fmt.Errorf("delete VRFNameNeighbor %s: %w", req.State.Name, err)
	}
	saveIfEnabled(ctx)
	return infer.DeleteResponse{}, nil
}

